// Shared camera and post-processing look for the Opus 5.5 vs Gemini 4 Argon battle.
// Both models' scenes use this file unchanged, so field of view, depth of field, ambient occlusion, bloom,
// anti-aliasing, tone mapping, vignette, grain and handheld sway are identical on both sides of the video.
// Do not edit this file and do not add any other screen-space pass. Everything inside the scene is yours.
//
// Usage:
//   import { createBattleLook } from './battle-look.js';
//   const look = createBattleLook({ renderer, scene, camera });
//   // every frame, instead of renderer.render(scene, camera):
//   look.render(deltaTime);
//   // on resize:
//   look.setSize(width, height);
//   // toolbar and window.battle.setToggle:
//   look.setDof(true | false);
//   look.setDslr(true | false);
//
// Requires three@0.180.0 with the import map entries `three` and `three/addons/`.
//
// The scene is rendered once, with its own materials, into a target that keeps its depth buffer. Ambient
// occlusion, depth of field and the focus measurement all read that depth, so vertex-shader motion, alpha-tested
// leaves and hidden helper meshes are seen exactly as they appear in the picture.
import * as THREE from 'three';
import { EffectComposer } from 'three/addons/postprocessing/EffectComposer.js';
import { Pass, FullScreenQuad } from 'three/addons/postprocessing/Pass.js';
import { GTAOPass } from 'three/addons/postprocessing/GTAOPass.js';
import { UnrealBloomPass } from 'three/addons/postprocessing/UnrealBloomPass.js';
import { OutputPass } from 'three/addons/postprocessing/OutputPass.js';
import { ShaderPass } from 'three/addons/postprocessing/ShaderPass.js';
import { BokehShader } from 'three/addons/shaders/BokehShader.js';
import { CopyShader } from 'three/addons/shaders/CopyShader.js';

export const BATTLE_LOOK = Object.freeze({
  verticalFieldOfViewDegrees: 50,
  pixelRatio: 1,
  // Recording (?capture=1) renders at twice the resolution and the browser scales it down: 2x supersampling on top
  // of MSAA, so thin wires, foliage and specular edges stay clean in the video.
  capturePixelRatio: 2,
  multisampleCount: 4,
  ambientOcclusion: { radius: 0.6, distanceExponent: 1.4, thickness: 1.0, scale: 1.0, blendIntensity: 0.85 },
  bloom: { strength: 0.32, radius: 0.55, threshold: 0.92 },
  depthOfField: { aperture: 0.0006, maxBlur: 0.005, focusSmoothingPerSecond: 4.0, nearestFocus: 0.8, farthestFocus: 400 },
  dslr: { vignette: 0.32, grain: 0.035, swayYawRadians: 0.006, swayPitchRadians: 0.004 },
});

const finishShader = {
  uniforms: {
    tDiffuse: { value: null },
    vignetteAmount: { value: 0 },
    grainAmount: { value: 0 },
    grainSeed: { value: 0 },
  },
  vertexShader: /* glsl */ `
    varying vec2 vUv;
    void main() {
      vUv = uv;
      gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
    }
  `,
  fragmentShader: /* glsl */ `
    uniform sampler2D tDiffuse;
    uniform float vignetteAmount;
    uniform float grainAmount;
    uniform float grainSeed;
    varying vec2 vUv;
    float hash(vec2 point) {
      return fract(sin(dot(point, vec2(12.9898, 78.233)) + grainSeed) * 43758.5453);
    }
    void main() {
      vec4 color = texture2D(tDiffuse, vUv);
      vec2 centered = vUv - 0.5;
      float vignette = 1.0 - vignetteAmount * smoothstep(0.25, 0.85, length(centered * vec2(1.15, 1.0)));
      float grain = (hash(vUv * 1000.0) - 0.5) * grainAmount;
      gl_FragColor = vec4(color.rgb * vignette + grain, color.a);
    }
  `,
};

// Copies a small window around the screen centre of the depth texture into an 8 x 8 float target.
const centreDepthShader = {
  uniforms: {
    tDepth: { value: null },
    windowSize: { value: 0.04 },
  },
  vertexShader: /* glsl */ `
    varying vec2 vUv;
    void main() {
      vUv = uv;
      gl_Position = vec4(position.xy, 0.0, 1.0);
    }
  `,
  fragmentShader: /* glsl */ `
    uniform sampler2D tDepth;
    uniform float windowSize;
    varying vec2 vUv;
    void main() {
      vec2 sampleUv = 0.5 + (vUv - 0.5) * windowSize;
      gl_FragColor = vec4(texture2D(tDepth, sampleUv).x, 0.0, 0.0, 1.0);
    }
  `,
};

// Renders the scene with its own materials into a target that keeps depth, then copies the colour onward.
class SceneDepthPass extends Pass {
  constructor(scene, camera, sceneTarget) {
    super();
    this.scene = scene;
    this.camera = camera;
    this.sceneTarget = sceneTarget;
    this.needsSwap = false;
    this.copyQuad = new FullScreenQuad(new THREE.ShaderMaterial({
      uniforms: THREE.UniformsUtils.clone(CopyShader.uniforms),
      vertexShader: CopyShader.vertexShader,
      fragmentShader: CopyShader.fragmentShader,
      depthTest: false,
      depthWrite: false,
    }));
  }

  render(renderer, writeBuffer, readBuffer) {
    renderer.setRenderTarget(this.sceneTarget);
    renderer.clear();
    renderer.render(this.scene, this.camera);
    this.copyQuad.material.uniforms.tDiffuse.value = this.sceneTarget.texture;
    renderer.setRenderTarget(readBuffer);
    this.copyQuad.render(renderer);
  }
}

function createFocusProbe(renderer, depthTexture) {
  const probeSize = 8;
  const target = new THREE.WebGLRenderTarget(probeSize, probeSize, { type: THREE.FloatType });
  const quad = new FullScreenQuad(new THREE.ShaderMaterial({
    uniforms: THREE.UniformsUtils.clone(centreDepthShader.uniforms),
    vertexShader: centreDepthShader.vertexShader,
    fragmentShader: centreDepthShader.fragmentShader,
    depthTest: false,
    depthWrite: false,
  }));
  quad.material.uniforms.tDepth.value = depthTexture;
  const pixels = new Float32Array(probeSize * probeSize * 4);

  // Returns the median distance in front of the camera over the centre window, from the last rendered frame.
  function measureCentreDistance(camera) {
    const previousTarget = renderer.getRenderTarget();
    renderer.setRenderTarget(target);
    quad.render(renderer);
    renderer.readRenderTargetPixels(target, 0, 0, probeSize, probeSize, pixels);
    renderer.setRenderTarget(previousTarget);

    const distances = [];
    for (let index = 0; index < probeSize * probeSize; index++) {
      const depth = pixels[index * 4];
      if (depth >= 0.9999) {
        continue;
      }
      const normalizedDeviceZ = depth * 2 - 1;
      const viewZ = (2 * camera.near * camera.far) / (camera.far + camera.near - normalizedDeviceZ * (camera.far - camera.near));
      distances.push(viewZ);
    }
    if (distances.length === 0) {
      return BATTLE_LOOK.depthOfField.farthestFocus;
    }
    distances.sort((first, second) => first - second);
    return distances[Math.floor(distances.length / 2)];
  }

  return { measureCentreDistance };
}

function createDepthOfFieldPass(depthTexture) {
  const shader = {
    defines: { DEPTH_PACKING: 0, PERSPECTIVE_CAMERA: 1 },
    uniforms: THREE.UniformsUtils.clone(BokehShader.uniforms),
    vertexShader: BokehShader.vertexShader,
    fragmentShader: BokehShader.fragmentShader,
  };
  const pass = new ShaderPass(shader, 'tColor');
  pass.uniforms.tDepth.value = depthTexture;
  pass.uniforms.aperture.value = BATTLE_LOOK.depthOfField.aperture;
  pass.uniforms.maxblur.value = BATTLE_LOOK.depthOfField.maxBlur;
  return pass;
}

export function createBattleLook({ renderer, scene, camera }) {
  const width = renderer.domElement.clientWidth || window.innerWidth;
  const height = renderer.domElement.clientHeight || window.innerHeight;

  const isCapture = typeof location !== 'undefined' && new URLSearchParams(location.search).has('capture');
  const pixelRatio = isCapture ? BATTLE_LOOK.capturePixelRatio : BATTLE_LOOK.pixelRatio;
  renderer.setPixelRatio(pixelRatio);
  renderer.toneMapping = THREE.ACESFilmicToneMapping;
  renderer.outputColorSpace = THREE.SRGBColorSpace;

  const sceneTarget = new THREE.WebGLRenderTarget(width * pixelRatio, height * pixelRatio, {
    type: THREE.HalfFloatType,
    samples: BATTLE_LOOK.multisampleCount,
    depthTexture: new THREE.DepthTexture(width * pixelRatio, height * pixelRatio),
  });
  const composerTarget = new THREE.WebGLRenderTarget(width, height, { type: THREE.HalfFloatType });
  const composer = new EffectComposer(renderer, composerTarget);
  composer.setPixelRatio(pixelRatio);

  const scenePass = new SceneDepthPass(scene, camera, sceneTarget);
  const ambientOcclusionPass = new GTAOPass(scene, camera, width, height);
  ambientOcclusionPass.setGBuffer(sceneTarget.depthTexture, undefined);
  ambientOcclusionPass.updateGtaoMaterial({
    radius: BATTLE_LOOK.ambientOcclusion.radius,
    distanceExponent: BATTLE_LOOK.ambientOcclusion.distanceExponent,
    thickness: BATTLE_LOOK.ambientOcclusion.thickness,
    scale: BATTLE_LOOK.ambientOcclusion.scale,
  });
  ambientOcclusionPass.blendIntensity = BATTLE_LOOK.ambientOcclusion.blendIntensity;
  const bloomPass = new UnrealBloomPass(new THREE.Vector2(width, height), BATTLE_LOOK.bloom.strength, BATTLE_LOOK.bloom.radius, BATTLE_LOOK.bloom.threshold);
  const depthOfFieldPass = createDepthOfFieldPass(sceneTarget.depthTexture);
  const outputPass = new OutputPass();
  const finishPass = new ShaderPass(finishShader);

  composer.addPass(scenePass);
  composer.addPass(ambientOcclusionPass);
  composer.addPass(bloomPass);
  composer.addPass(depthOfFieldPass);
  composer.addPass(outputPass);
  composer.addPass(finishPass);

  const focusProbe = createFocusProbe(renderer, sceneTarget.depthTexture);
  const state = { dof: true, dslr: true, focusDistance: 10, elapsedSeconds: 0, clockSeconds: null, frameIndex: 0, width, height };

  function enforceCamera() {
    if (camera.fov !== BATTLE_LOOK.verticalFieldOfViewDegrees) {
      camera.fov = BATTLE_LOOK.verticalFieldOfViewDegrees;
      camera.updateProjectionMatrix();
    }
  }

  function updateFocus(deltaTime) {
    const measured = focusProbe.measureCentreDistance(camera);
    const clamped = THREE.MathUtils.clamp(measured, BATTLE_LOOK.depthOfField.nearestFocus, BATTLE_LOOK.depthOfField.farthestFocus);
    const blend = 1 - Math.exp(-BATTLE_LOOK.depthOfField.focusSmoothingPerSecond * Math.max(deltaTime, 0));
    state.focusDistance = state.frameIndex <= 1 ? clamped : state.focusDistance + (clamped - state.focusDistance) * blend;
  }

  function swayOffsets() {
    const time = state.elapsedSeconds;
    const yaw = (Math.sin(time * 0.71) * 0.6 + Math.sin(time * 1.37 + 1.2) * 0.4) * BATTLE_LOOK.dslr.swayYawRadians;
    const pitch = (Math.sin(time * 0.53 + 0.4) * 0.6 + Math.sin(time * 1.13 + 2.1) * 0.4) * BATTLE_LOOK.dslr.swayPitchRadians;
    return { yaw, pitch };
  }

  function updateDepthOfFieldUniforms() {
    depthOfFieldPass.enabled = state.dof;
    depthOfFieldPass.uniforms.focus.value = state.focusDistance;
    depthOfFieldPass.uniforms.nearClip.value = camera.near;
    depthOfFieldPass.uniforms.farClip.value = camera.far;
    depthOfFieldPass.uniforms.aspect.value = state.height / state.width;
  }

  // Returns the seconds that passed since the last render. With an external clock (the recorder sets it once per
  // video frame), extra renders inside one frame pass no time, so sway and focus move the same on every build.
  function advanceClock(deltaTime) {
    if (state.clockSeconds === null) {
      state.elapsedSeconds += deltaTime;
      return deltaTime;
    }
    const passedSeconds = Math.max(0, state.clockSeconds - state.elapsedSeconds);
    state.elapsedSeconds = state.clockSeconds;
    return passedSeconds;
  }

  function render(deltaTime = 1 / 60) {
    enforceCamera();
    const passedSeconds = advanceClock(deltaTime);
    updateDepthOfFieldUniforms();
    finishPass.uniforms.vignetteAmount.value = state.dslr ? BATTLE_LOOK.dslr.vignette : 0;
    finishPass.uniforms.grainAmount.value = state.dslr ? BATTLE_LOOK.dslr.grain * pixelRatio : 0;
    finishPass.uniforms.grainSeed.value = (state.frameIndex % 997) * 0.37;

    const savedQuaternion = camera.quaternion.clone();
    if (state.dslr) {
      const { yaw, pitch } = swayOffsets();
      camera.rotateY(yaw);
      camera.rotateX(pitch);
      camera.updateMatrixWorld();
    }
    composer.render(deltaTime);
    camera.quaternion.copy(savedQuaternion);
    camera.updateMatrixWorld();
    state.frameIndex++;

    // Focus for the next frame comes from the depth of the frame just drawn.
    if (state.dof) {
      updateFocus(passedSeconds);
    }
  }

  function setSize(newWidth, newHeight) {
    state.width = newWidth;
    state.height = newHeight;
    camera.aspect = newWidth / newHeight;
    camera.updateProjectionMatrix();
    renderer.setSize(newWidth, newHeight);
    sceneTarget.setSize(newWidth * pixelRatio, newHeight * pixelRatio);
    composer.setSize(newWidth, newHeight);
  }

  function setDof(enabled) {
    state.dof = Boolean(enabled);
  }

  function setDslr(enabled) {
    state.dslr = Boolean(enabled);
  }

  function setClock(seconds) {
    const nextClock = seconds === null ? null : Number(seconds);
    if (state.clockSeconds === null && nextClock !== null) {
      state.elapsedSeconds = nextClock;
    }
    state.clockSeconds = nextClock;
  }

  const api = {
    setClock,
    render,
    setSize,
    setDof,
    setDslr,
    get dof() {
      return state.dof;
    },
    get dslr() {
      return state.dslr;
    },
    get focusDistance() {
      return state.focusDistance;
    },
  };
  // The recorder drives the clock through this handle; builds do not need to touch it.
  if (typeof window !== 'undefined') {
    window.battleLook = api;
  }
  return api;
}
